:root {
  --reading-border: #223151;
  --reading-background: #D7D8DB;
  --reading-field-background: #E5E8EB;

  --reading-title-color: #930606;
  --reading-value-color: #000000;
  --reading-unit-color: #0A638F;

  --reading-scale: 1;
  --reading-layout-width: 200px;
  --reading-frame-border: 1px;
  --reading-frame-radius: 5px;
}

html,
body {
  width: 100%;
  height: 100%;
  margin: 0;
  padding: 0;
  overflow: hidden;
  background: transparent !important;
}

.reading-widget,
.reading-widget * {
  box-sizing: border-box;
}

.reading-widget {
  position: relative;
  width: 100%;
  height: 100%;
  overflow: hidden;

  background: transparent;
  pointer-events: none;
  user-select: none;
  opacity: var(--w-opacity, 1);
}

/* El marco ocupa todo el ancho y alto del widget. */
.reading-card {
  position: absolute;
  inset: 0;

  overflow: hidden;
  border-radius: var(--reading-frame-radius);
  background: var(--reading-background);

  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.50),
    inset 0 -1px 0 rgba(85, 93, 105, 0.12);
}

.reading-card::after {
  content: "";
  position: absolute;
  inset: 0;

  border:
    var(--reading-frame-border)
    solid
    var(--reading-border);

  border-radius: inherit;
  pointer-events: none;
}

/* Escalado uniforme y centrado en ambas direcciones. */
.reading-layout {
  position: absolute;
  left: 50%;
  top: 50%;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 3px;

  width: var(--reading-layout-width);
  height: 75px;
  padding: 6px 11px;

  transform:
    translate(-50%, -50%)
    scale(var(--reading-scale));

  transform-origin: center;
}

.reading-title {
  display: block;
  flex: 0 0 auto;

  width: max-content;
  min-height: 18px;
  margin: 0;
  padding: 0;

  color: var(--reading-title-color);

  font-family:
    "Bahnschrift",
    "Segoe UI",
    Arial,
    sans-serif;

  font-size: 16px;
  font-weight: 700;
  font-style: italic;
  font-kerning: normal;
  line-height: 18px;

  letter-spacing: 0;
  word-spacing: 0;
  text-align: center;
  text-indent: 0;

  /* Conserva el salto de línea definido desde NOMBRE. */
  white-space: pre;
}

.reading-row {
  display: flex;
  flex: 0 0 auto;
  align-items: center;
  justify-content: center;
  gap: 7px;

  width: max-content;
  height: 22px;

  font-family:
    "IBM Plex Mono",
    Consolas,
    "Liberation Mono",
    monospace;

  font-size: 14px;
  font-weight: 600;
  font-style: normal;
  font-variant-numeric: tabular-nums;
  font-variant-ligatures: none;
  line-height: 18px;

  letter-spacing: 0;
  word-spacing: 0;
}

.reading-field {
  display: flex;
  flex: 0 0 auto;
  align-items: center;
  justify-content: center;

  width: max-content;
  min-width: 64px;
  height: 22px;
  padding: 0 8px;

  border: 1px solid #738594;
  border-radius: 3px;
  background: var(--reading-field-background);

  box-shadow:
    inset 0 1px 2px rgba(34, 49, 81, 0.10),
    inset 0 -1px 0 rgba(255, 255, 255, 0.40);
}

.reading-value,
.reading-unit {
  display: block;
  flex: 0 0 auto;

  font-family: inherit;
  font-size: inherit;
  font-weight: inherit;
  font-style: inherit;
  line-height: inherit;

  letter-spacing: 0;
  word-spacing: 0;
  text-align: center;
  white-space: nowrap;
}

.reading-value {
  color: var(--reading-value-color);
}

.reading-unit {
  color: var(--reading-unit-color);
}

.reading-unit[hidden] {
  display: none;
}

.reading-layout {
  padding: 4px 11px;
  gap: 2px;
}

.reading-row {
  height: 28px;
  font-size: 18px;
  line-height: 22px;
}

.reading-field {
  min-width: 84px;
  height: 28px;
  padding: 0 10px;
}

