"use strict";

(function () {
  const BASE_WIDTH = 200;
  const BASE_HEIGHT = 75;
  const CONTENT_MARGIN = 28;

  const DEFAULT_TITLE =
    "Tiempo para Activar\nParadas por Software";

  const DEFAULT_UNIT = "min";

  let container = null;
  let titleElement = null;
  let rowElement = null;
  let valueElement = null;
  let unitElement = null;

  let lastUpdate = null;
  let resizeObserver = null;
  let pendingFrame = null;

  function normalizeSpaces(text) {
    return String(text)
      .replace(/\s+/g, " ")
      .trim();
  }

  function stripQuotes(text) {
    return String(text)
      .trim()
      .replace(/^["“]([\s\S]*)["”]$/, "$1");
  }

  function cleanText(text) {
    return normalizeSpaces(stripQuotes(text));
  }

  function cleanTitle(text) {
    /*
     * "//" indica el salto de línea.
     * También admite un salto real o el texto literal \n.
     */
    const parts = stripQuotes(text)
      .split(/\/\/|\\n|\r\n|\n|\r/)
      .map(normalizeSpaces)
      .filter(function (part) {
        return part !== "";
      });

    if (parts.length === 0) {
      return DEFAULT_TITLE;
    }

    if (parts.length === 1) {
      return parts[0];
    }

    // Como máximo se muestran dos líneas.
    return parts[0] + "\n" + parts.slice(1).join(" ");
  }

  function parseName(name) {
    const text =
      typeof name === "string"
        ? name.trim()
        : "";

    if (!text) {
      return {
        title: DEFAULT_TITLE,
        unit: DEFAULT_UNIT
      };
    }

    /*
     * Formato recomendado:
     * Primera línea // Segunda línea | min
     *
     * También admite el formato anterior:
     * "Primera línea // Segunda línea"_"min"
     */
    const quotedFormat = text.match(
      /^"([^"]*)"\s*_\s*"([^"]*)"$/
    );

    if (quotedFormat) {
      return {
        title: cleanTitle(quotedFormat[1]),
        unit: cleanText(quotedFormat[2])
      };
    }

    const separatorIndex = text.lastIndexOf("|");

    if (separatorIndex >= 0) {
      return {
        title: cleanTitle(text.slice(0, separatorIndex)),
        unit: cleanText(text.slice(separatorIndex + 1))
      };
    }

    // Sin "|" se muestra el título sin unidad.
    return {
      title: cleanTitle(text),
      unit: ""
    };
  }

  function resizeLayout() {
    if (!container || !titleElement || !rowElement) {
      return;
    }

    const availableWidth = container.clientWidth;
    const availableHeight = container.clientHeight;

    if (availableWidth <= 0 || availableHeight <= 0) {
      return;
    }

    /*
     * El ancho natural contempla la línea más larga
     * del título y el conjunto de valor y unidad.
     */
    const naturalWidth = Math.ceil(
      Math.max(
        BASE_WIDTH,
        titleElement.scrollWidth + CONTENT_MARGIN,
        rowElement.scrollWidth + CONTENT_MARGIN
      )
    );

    container.style.setProperty(
      "--reading-layout-width",
      naturalWidth + "px"
    );

    /*
     * El contenido se ajusta al espacio asignado por
     * el editor, conservando las proporciones.
     */
    const scale = Math.min(
      availableWidth / naturalWidth,
      availableHeight / BASE_HEIGHT
    );

    container.style.setProperty(
      "--reading-scale",
      String(scale)
    );

    container.style.setProperty(
      "--reading-frame-border",
      scale + "px"
    );

    container.style.setProperty(
      "--reading-frame-radius",
      (5 * scale) + "px"
    );
  }

  function scheduleLayout() {
    if (pendingFrame !== null) return;

    pendingFrame = requestAnimationFrame(function () {
      pendingFrame = null;
      resizeLayout();
    });
  }

  function render(w) {
    if (
      !titleElement ||
      !rowElement ||
      !valueElement ||
      !unitElement
    ) {
      return;
    }

    const config = parseName(w && w.name);

    titleElement.textContent = config.title;
    unitElement.textContent = config.unit;
    unitElement.hidden = config.unit === "";

    const raw = w ? w.value : null;
    let numericValue = NaN;

    if (typeof raw === "number") {
      numericValue = raw;
    } else if (
      typeof raw === "string" &&
      raw.trim() !== ""
    ) {
      numericValue = Number(raw);
    }

    const valid = Number.isFinite(numericValue);
    const text = valid ? String(numericValue) : "—";

    // Conserva el dato sin redondearlo ni convertir unidades.
    valueElement.textContent = text;

    const accessibleTitle = normalizeSpaces(config.title);

    rowElement.setAttribute(
      "aria-label",
      valid
        ? accessibleTitle + ": " + text +
          (config.unit ? " " + config.unit : "")
        : accessibleTitle + ": sin valor numérico"
    );

    scheduleLayout();
  }

  window.onWidgetUpdate = function (w) {
    lastUpdate = w;
    render(w);
  };

  function initialize() {
    container = document.querySelector(".reading-widget");
    titleElement = document.querySelector(".reading-title");
    rowElement = document.querySelector(".reading-row");
    valueElement = document.querySelector(".reading-value");
    unitElement = document.querySelector(".reading-unit");

    if (
      !container ||
      !titleElement ||
      !rowElement ||
      !valueElement ||
      !unitElement
    ) {
      return;
    }

    render(lastUpdate || window.WIDGET || null);
    resizeLayout();

    if (document.fonts && document.fonts.ready) {
      document.fonts.ready.then(scheduleLayout);
    }

    if (typeof ResizeObserver !== "undefined") {
      resizeObserver = new ResizeObserver(scheduleLayout);
      resizeObserver.observe(container);
    } else {
      window.addEventListener("resize", scheduleLayout);
    }
  }

  if (document.readyState === "loading") {
    document.addEventListener(
      "DOMContentLoaded",
      initialize,
      { once: true }
    );
  } else {
    initialize();
  }
})();
